[
  {
    "ce_mentalizing_difficulty": "I just can't read what's going on in their head.",
    "pd_personal_consequence_anxiety": "makes me a bit uneasy that they might file me away",
    "sys_fairness_reciprocity": "We did identical work, so anything else would feel crooked to me.",
    "pda_self_consequence_regret": "I'd really regret losing their good opinion over one question"
  },
  {
    "ce_mentalizing_difficulty": "Even with every fact laid out, I can't predict that about them.",
    "pd_personal_consequence_anxiety": "The thought of them pulling away from me makes my stomach tighten.",
    "sys_fairness_reciprocity": "Equal hours, equal effort, equal thanks."
  },
  {
    "ce_mentalizing_difficulty": "Nothing in the story is hidden there; I just can't read them.",
    "pd_personal_consequence_anxiety": "I get nervous picturing myself as the gatekeeper of someone else's pay",
    "pda_self_consequence_regret": "I'd hate to end up regretting a reputation I didn't ask for."
  },
  {
    "ce_mentalizing_difficulty": "That's a guessing-at-a-person problem, not a missing-fact problem.",
    "pd_personal_consequence_anxiety": "I'd be anxious that any pause on my end reads as petty.",
    "pda_self_consequence_regret": "If I lost their trust over a moment of hesitation, I'd kick myself"
  },
  {
    "ce_mentalizing_difficulty": "I honestly can't read their expectations, even knowing the whole setup.",
    "pd_personal_consequence_anxiety": "I'm a little scared that if they found out I was consulted",
    "sys_fairness_reciprocity": "Getting paid while they don't would feel wrong to me",
    "pda_self_consequence_regret": "That's a loss I'd regret badly"
  },
  {
    "ce_mentalizing_difficulty": "That's about reading them, not about gaps in the story.",
    "pd_personal_consequence_anxiety": "I'm uneasy about owing anyone a thank-you I don't deserve",
    "sys_fairness_reciprocity": "We split the work down the middle.",
    "pda_self_consequence_regret": "I'd regret getting tangled up as some kind of middleman."
  },
  {
    "ce_mentalizing_difficulty": "I genuinely can't decode that, and more facts wouldn't obviously fix it",
    "pd_personal_consequence_anxiety": "Being blamed later honestly worries me.",
    "pda_self_consequence_regret": "I'd regret that for my standing in the community."
  },
  {
    "ce_mentalizing_difficulty": "That's hard to read regardless of the facts given.",
    "pd_personal_consequence_anxiety": "I get jittery imagining my coworker hearing I had the final word.",
    "sys_fairness_reciprocity": "Apply the same standard you used for me.",
    "pda_self_consequence_regret": "I'd regret losing their easy trust in me"
  },
  {
    "ce_mentalizing_difficulty": "That's not the scenario leaving gaps; they're just a tough person to figure out.",
    "pd_personal_consequence_anxiety": "I worry they might think I was dangling something over them",
    "sys_fairness_reciprocity": "Equal work gets equal thanks, full stop."
  },
  {
    "ce_mentalizing_difficulty": "I can't read their intentions, even with the facts clear.",
    "pd_personal_consequence_anxiety": "makes me nervous that my answer could shape how they see me going forward.",
    "sys_fairness_reciprocity": "Anything less would feel unfair to me given we did the same work.",
    "pda_self_consequence_regret": "If I came across as small-minded, I'd regret that."
  }
]
